edits.after:
emit OWNER_LANE_NET $net PIN_COUNT [llength [get_pins -quiet -of_objects $net]]
# UG835 2026.1 all_fanin accepts a sink net as its positional object.
# Full timing-startpoint lists are retained; no netlist property is edited.
if {[llength $nets] <= 32} {
    if {[catch {lsort [all_fanin -flat -startpoints_only $net]} starts]} {
        gap $net OWNER_FANIN_UNAVAILABLE $starts
    } else {
        emit OWNER_LANE_FANIN $net STARTPOINT_COUNT [llength $starts]
        emit OWNER_LANE_FANIN $net STARTPOINTS $starts
        if {[llength $starts]==0} {gap $net NO_FANIN_STARTPOINTS {No topology claim from an empty fan-in observation}}
    }
} else {
    gap $pattern OWNER_FANIN_NOT_QUERIED {More than 32 named lane nets; bounded fan-in query not executed}
}
